head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_pf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
scwin.vScrenID = "ULDSTF09350.xml";
scwin.pJobTitl = js_jobtitl;
scwin.vACPT_NO = "";
scwin.vISU_CD = "";
scwin.vISU_KOR_ABBRV = "";
scwin.secugrpId = 'PF';
scwin.secugrpNm = '상장형수익증권';
//var listBzTpCd = LIST_BZ_TP_CD_813; // PF 매매거래정지
scwin.vSearchDate = "";
scwin.loding1, scwin.loding2, scwin.loding3, scwin.loding4, scwin.loding5, scwin.loding6;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_date_err_check = function() {
    if ($c.stf.getObjectValue(edt_ConfirmDate) == "" || edt_ConfirmDate.Text.length < 8) {
        $c.win.alert("마감일을 입력하세요.");
        edt_ConfirmDate.focus();
        return true;
    }
};
scwin.fn_list_sync = function() {
    if (scwin.fn_date_err_check()) {
        return;
    }
    $c.cm.ShowWin(grd_List3);
    loading1 = false;
    loading2 = false;
    loading3 = false;
    loading4 = false;
    loading5 = false;
    loading6 = false;
    var nowOld = "NOW";
    var curDd = $c.ut.cGetToday("yyyymmdd");
    var searchDate = $c.stf.getObjectValue(edt_ConfirmDate);
    //마감일이 오늘이 아니면 이력조회
    if (curDd != searchDate) {
        nowOld = "OLD";
    }
    scwin.fn_clslog_sync();
    //팀장 마감이 되었다면 이력조회
    var apprvEmpNm = $c.stf.getObjectValue(txb_APPROVR_EMP_NM);
    if (apprvEmpNm.length > 0) {
        nowOld = "OLD";
    }
    scwin.vSearchDate = $c.stf.getObjectValue(edt_ConfirmDate);
    scwin.getJungBoBatch();
    scwin.fn_list_dtl("01", nowOld);
    scwin.fn_list_dtl("02", nowOld);
    scwin.fn_list_dtl("03", nowOld);
    scwin.fn_list_dtl("04", nowOld);
    scwin.fn_list_dtl("05", nowOld);
    scwin.fn_list_dtl("06", nowOld);
};
scwin.fn_list_dtl = function(type, nowOld) {
    var urlcond = '';
    var datasetId = "";
    urlcond += "&BAS_DD=" + $c.stf.getObjectValue(edt_ConfirmDate);
    urlcond += "&SECUGRP_ID=" + scwin.secugrpId;
    if (nowOld == "OLD") {
        if (type == "01") {
            //최초적출
            urlcond += "&ETP_INVSTWARN_CD=" + "01";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List1;
        } else if (type == "02") {
            //지정예고
            urlcond += "&ETP_INVSTWARN_CD=" + "02";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List2;
        } else if (type == "04") {
            // 지정연장
            urlcond += "&ETP_INVSTWARN_CD=" + "04";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List3;
        } else if (type == "03") {
            //지정
            urlcond += "&ETP_INVSTWARN_CD=" + "03";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List4;
        } else if (type == "05") {
            //지정해제
            urlcond += "&ETP_INVSTWARN_CD=" + "05";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List5;
        } else if (type == "06") {
            //매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            urlcond += "&ETP_INVSTWARN_CD=" + "06";
            var url_list = "/pf/InvstwarnClose.do?method=selectOldList";
            datasetId = dts_List6;
        }
    } else {
        if (type == "01") {
            //최초적출
            var url_list = "/pf/InvstwarnClose.do?method=selectFirstDetect";
            datasetId = dts_List1;
        } else if (type == "02") {
            //지정예고
            var url_list = "/pf/InvstwarnClose.do?method=selectNoti";
            datasetId = dts_List2;
        } else if (type == "04") {
            // 지정연장
            var url_list = "/pf/InvstwarnClose.do?method=selectExtn";
            datasetId = dts_List3;
        } else if (type == "03") {
            //지정
            var url_list = "/pf/InvstwarnClose.do?method=selectDesign";
            datasetId = dts_List4;
        } else if (type == "05") {
            //지정해제
            var url_list = "/pf/InvstwarnClose.do?method=selectRelease";
            datasetId = dts_List5;
        } else if (type == "06") {
            //매매거래정지, 매매거래정지 해제, 매매거래정지 및 해제
            urlcond += "&LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_813;
            var url_list = "/pf/InvstwarnClose.do?method=selectTrdHalt";
            datasetId = dts_List6;
        }
    }
    url_list += urlcond;
    url_list += "&SCREN_ID=" + scwin.vScrenID;
    url_list += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    datasetId.DataID = encodeURI(url_list);
    datasetId.Reset();
};


/********************************************** 
 * 함수명   : fn_ExcelDown()
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    //파일형식 today_화면명.xls
    var xls_path = $c.session.getExcelDownPath() + today + scwin.secugrpNm + "투자유의종목마감.xls";
    $c.data.saveExcel(grd_List1, "최초적출", false, false, false, xls_path);
    if (dts_List2.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List2, "지정예고", xls_path, 40);
    }
    if (dts_List3.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List3, "지정연장", xls_path, 40);
    }
    if (dts_List4.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List4, "지정", xls_path, 40);
    }
    if (dts_List5.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List5, "지정해제", xls_path, 40);
    }
    if (dts_List6.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_List6, "매매거래정지", xls_path, 40);
    }
};



//마감가능여부 체크
scwin.chkIsClose = function() {
    var isCheck = true;
    var curDd = $c.ut.cGetToday("yyyymmdd");
    var searchDate = $c.stf.getObjectValue(edt_ConfirmDate);
    if (curDd != searchDate || scwin.vSearchDate != curDd) {
        $c.win.alert("당일날짜만 마감가능합니다. 마감일을 확인하세요");
        isCheck = false;
    }
    return isCheck;
};


//담당자 확인 버튼 클릭시
scwin.fn_revw = function() {
    procJob = "담당자 확인";
    if (scwin.chkIsClose()) {
        var res = window.confirm(procJob + " 마감처리 하시겠습니까?");
        if (res) {
            scwin.fn_trs_revw();
        }
    }
};




// 팀장승인 버튼 클릭시
scwin.fn_aprv = function() {
    if (loading1 && loading2 && loading3 && loading4 && loading5 && loading6) {
        if (scwin.chkIsClose()) {
            procJob = "팀장승인";
            if ($c.stf.getObjectValue(txb_CONFRM_DDTM) == "") {
                $c.win.alert("담당자확인 완료 후 승인처리 가능합니다.");
                return false;
            } else {
                var res = window.confirm(procJob + " 마감처리 하시겠습니까?");
                if (res) {
                    scwin.fn_trs_aprv();
                }
            }
        }
    } else {
        $c.win.alert("데이터가 로딩중입니다. 로딩후에 승인가능합니다.");
    }
};



//담당자 확인
scwin.fn_trs_revw = function() {
    scwin.fn_trSetHeader();
    dts_Cls.setCellData(1, "EMP_NO", js_emp_no);
    dts_Cls.setCellData(1, "SECUGRP_ID", scwin.secugrpId);
    trs_revw.Action = "/pf/InvstwarnClose.do?method=revwFinalSave" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_revw.KeyName = "toinb_dataid4";
    trs_revw.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_revw.Post();
};


//팀장승인 
scwin.fn_trs_aprv = function() {
    scwin.fn_trSetHeader();
    dts_Cls.setCellData(1, "EMP_NO", js_emp_no);
    dts_Cls.setCellData(1, "SECUGRP_ID", scwin.secugrpId);
    trs_aprv.Action = "/pf/InvstwarnClose.do?method=apprvFinalSave&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_aprv.KeyName = "toinb_dataid4";
    trs_aprv.KeyValue = "JSP(I:pInput=dts_Cls,I:pInput2=dts_List1,I:pInput3=dts_List2,I:pInput4=dts_List3,I:pInput5=dts_List4,I:pInput6=dts_List5,I:pInput7=dts_List6)";
    trs_aprv.Post();
};


// 담당자 승인, 팀장승인
scwin.buttonSetDis = function() {
    //담당자일때
    if (scwin.pJobTitl == "03") {
        if ($c.stf.getObjectValue(txb_CONFRM_DDTM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_BosApv.src = "../img/btn_BosApv_d.gif";
            btn_BosApv.setDisabled(true);
        } else {
            btn_Revw.src = "../img/btn/btn_revw.gif";
            btn_Revw.setDisabled(false);
            btn_BosApv.src = "../img/btn_BosApv_d.gif";
            btn_BosApv.setDisabled(true);
        }
    } else {
        //팀장일때 - 마감처리
        if ($c.stf.getObjectValue(txb_CONFRM_DDTM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
        } else {
            btn_Revw.src = "../img/btn/btn_revw.gif";
            btn_Revw.setDisabled(false);
        }
        if ($c.stf.getObjectValue(txb_APPROV_DDTM) != "") {
            btn_BosApv.src = "../img/btn_BosApv_d.gif";
            btn_BosApv.setDisabled(true);
        } else {
            btn_BosApv.src = "../img/btn_BosApv.gif";
            btn_BosApv.setDisabled(false);
        }
    }
};




// 담당자 확인 불가처리
scwin.buttonSetNoData = function() {
    btn_Revw.src = "../img/btn/btn_revw_d.gif";
    btn_Revw.setDisabled(true);
};
scwin.fn_trSetHeader = function() {
    dts_Cls.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INVSTWARN_CLOSE_CLS";
    dts_Cls.reset();
    dts_Cls.insertRow();
};
scwin.fn_clslog_sync = function() {
    var url;
    url = "/pf/InvstwarnClose.do?method=searchFinalLog";
    url += "&BAS_DD=" + edt_ConfirmDate.getValue() + "&SECUGRP_ID=" + scwin.secugrpId;
    dts_sendLog.DataID = encodeURI(url);
    dts_sendLog.reset();
};
scwin.closeLoading = async function() {
    if (loading1 && loading2 && loading3 && loading4 && loading5 && loading6) {
        if ($c.frame.path("LoadingImg") != null) {
            await $c.frame.CloseFrame();
        }
        scwin.checkDupList();
    }
};



/********************************************** 
 * 함수명   : checkDupList
 * 설명      : 각 단계별 중복종목 리스트 체크
 ***********************************************/
scwin.checkDupList = function() {
    if (!scwin.loopDataSet(dts_List1)) {
        $c.win.alert("투자유의종목 최초적출 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List2)) {
        $c.win.alert("투자유의종목 지정예고 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List3)) {
        $c.win.alert("투자유의종목 지정연장 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List4)) {
        $c.win.alert("투자유의종목 지정 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List5)) {
        $c.win.alert("투자유의종목 지정해제 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
    if (!scwin.loopDataSet(dts_List6)) {
        $c.win.alert("투자유의종목 매매거래정지 단계에 중복된 종목이 있습니다. 확인하시기 바랍니다.");
    }
};
scwin.loopDataSet = function(dtsId) {
    var tempData = "";
    var checkData = "";
    for (var i = 1, j = dtsId.getTotalRow(); i <= j; i++) {
        tempData = dtsId.getCellData(i, "ISU_CD");
        for (var k = 1, l = dtsId.getTotalRow(); k <= l; k++) {
            if (i == k) {
                continue;
            }
            checkData = dtsId.getCellData(k, "ISU_CD");
            if (tempData == checkData) {
                return false;
            }
        }
    }
    return true;
};


/********************************************** 
 * 함수명   : getJungBoBatch
 * 설명      : 시장정보 배치실행 여부 가져오기
 ***********************************************/
scwin.getJungBoBatch = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=PF_INVSTWARNISU_CLS_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.pf.lstproc.invstwarn_md_progm_prog.select" + "&{P}param01=" + $c.ut.cGetToday("yyyymmdd");
    dts_batYn.DataID = encodeURI(url);
    dts_batYn.reset();
    $c.stf.setObjectValue(txb_ClsDtl, dts_batYn.getCellData(1, "CLS_YN"));
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    scwin.fn_ExcelDown();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_ConfirmDate.setValue(vCurDate);
    scwin.fn_list_sync();
    txb_cnt1.setValue(dts_List1.getTotalRow() + " 건");
    txb_cnt2.setValue(dts_List2.getTotalRow() + " 건");
    txb_cnt3.setValue(dts_List3.getTotalRow() + " 건");
    txb_cnt4.setValue(dts_List4.getTotalRow() + " 건");
    txb_cnt5.setValue(dts_List5.getTotalRow() + " 건");
    txb_cnt6.setValue(dts_List6.getTotalRow() + " 건");
};
scwin.btn_Revw_onclick = function() {
    scwin.fn_revw();
};
scwin.btn_BosApv_onclick = function() {
    scwin.fn_aprv();
};
scwin.img_ConfirmDate_onclick = function() {
    edt_ConfirmDate.focus();
    popUpCalendar2(edt_ConfirmDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List1_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    txb_cnt1.setValue(dts_List1.getTotalRow() + " 건");
    loading1 = true;
    scwin.closeLoading();
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    txb_cnt2.setValue(dts_List2.getTotalRow() + " 건");
    loading2 = true;
    scwin.closeLoading();
};
scwin.dts_List2_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    txb_cnt3.setValue(dts_List3.getTotalRow() + " 건");
    loading3 = true;
    scwin.closeLoading();
};
scwin.dts_List3_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_List4_OnLoadCompleted = function(rowcount) {
    txb_cnt4.setValue(dts_List4.getTotalRow() + " 건");
    loading4 = true;
    scwin.closeLoading();
};
scwin.dts_List4_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_List5_OnLoadCompleted = function(rowcount) {
    txb_cnt5.setValue(dts_List5.getTotalRow() + " 건");
    loading5 = true;
    scwin.closeLoading();
};
scwin.dts_List5_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.dts_List6_OnLoadCompleted = function(rowcount) {
    txb_cnt6.setValue(dts_List6.getTotalRow() + " 건");
    loading6 = true;
    scwin.closeLoading();
};
scwin.dts_List6_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002", ""));
};
scwin.trs_revw_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
};
scwin.trs_revw_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
    scwin.fn_list_sync();
};
scwin.dts_sendLog_OnLoadCompleted = function(rowcount) {
    scwin.buttonSetDis();
};
scwin.trs_aprv_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", procJob));
    scwin.fn_list_sync();
};
scwin.trs_aprv_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", procJob));
};
scwin.edt_ConfirmDate_OnKillFocus = function() {
    scwin.fn_list_sync();
};
